import type { OrderRepository } from '../../domain/repositories/OrderRepository';
import type { ProductRepository } from '../../domain/repositories/ProductRepository';
import type { StockAllocator } from '../../domain/services/StockAllocationService';
import { stockEffectOf, type OrderStatus } from '../../domain/value-objects/OrderStatus';
import type { Clock } from '../ports/Clock';
import { requireOrder, requireProducts } from './lookups';
import type { ChangeOrderStatusCommand, OrderAction, OrderDto } from './OrderDtos';
import { toOrderDto } from './OrderMapper';

const TARGET_STATUS: Readonly<Record<OrderAction, OrderStatus>> = {
  pay: 'paid',
  pack: 'packed',
  ship: 'shipped',
  deliver: 'delivered',
  cancel: 'cancelled',
};

export interface ChangeOrderStatus {
  execute(command: ChangeOrderStatusCommand): OrderDto;
}

/** Moves an order to its next state and settles its reserved stock where the state requires it. */
export class ChangeOrderStatusUseCase implements ChangeOrderStatus {
  constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
    private readonly stock: StockAllocator,
    private readonly clock: Clock,
  ) {}

  execute(command: ChangeOrderStatusCommand): OrderDto {
    const order = requireOrder(this.orders, command.orderId);
    const target = TARGET_STATUS[command.action];
    order.transitionTo(target, this.clock.now());

    const effect = stockEffectOf(target);
    if (effect !== 'none') {
      const products = requireProducts(
        this.products,
        order.lines.map((line) => line.productId),
      );
      if (effect === 'commit') {
        this.stock.commit(order.lines, products);
      } else {
        this.stock.release(order.lines, products);
      }
      products.forEach((product) => this.products.save(product));
    }

    this.orders.save(order);
    return toOrderDto(order);
  }
}

