import type { OrderRepository } from '../../domain/repositories/OrderRepository';
import { isOrderStatus, ORDER_STATUSES } from '../../domain/value-objects/OrderStatus';
import { ValidationError } from '../errors/ApplicationError';
import type { OrderDto } from './OrderDtos';
import { toOrderDto } from './OrderMapper';

export interface ListOrders {
  /** Lists all orders, or only those in the given state. */
  execute(status?: string): OrderDto[];
}

export class ListOrdersUseCase implements ListOrders {
  constructor(private readonly orders: OrderRepository) {}

  execute(status?: string): OrderDto[] {
    if (status === undefined) {
      return this.orders.findAll().map(toOrderDto);
    }
    if (!isOrderStatus(status)) {
      throw new ValidationError(
        `Unknown order status '${status}'; expected one of ${ORDER_STATUSES.join(', ')}`,
      );
    }
    return this.orders.findByStatus(status).map(toOrderDto);
  }
}

