import type { Order } from '../../domain/entities/Order';
import type { Product } from '../../domain/entities/Product';
import type { OrderRepository } from '../../domain/repositories/OrderRepository';
import type { ProductRepository } from '../../domain/repositories/ProductRepository';
import { NotFoundError } from '../errors/ApplicationError';

export function requireOrder(orders: OrderRepository, orderId: string): Order {
  const order = orders.findById(orderId);
  if (order === undefined) {
    throw new NotFoundError('Order', orderId);
  }
  return order;
}

/** Loads every listed product, keyed by id, failing on the first unknown one. */
export function requireProducts(
  products: ProductRepository,
  productIds: readonly string[],
): Map<string, Product> {
  const found = new Map<string, Product>();
  for (const productId of productIds) {
    const product = products.findById(productId);
    if (product === undefined) {
      throw new NotFoundError('Product', productId);
    }
    found.set(product.id, product);
  }
  return found;
}

/** Picks a product out of a map produced by {@link requireProducts}. */
export function productIn(products: ReadonlyMap<string, Product>, productId: string): Product {
  const product = products.get(productId);
  if (product === undefined) {
    throw new NotFoundError('Product', productId);
  }
  return product;
}

