import { ValidationError } from '../errors/ApplicationError';
import { requireArray, requireInteger, requireRecord, requireString } from '../validation/inputGuards';
import type { OrderItemInput, PlaceOrderCommand } from './OrderDtos';

export function parsePlaceOrderCommand(input: unknown): PlaceOrderCommand {
  const body = requireRecord(input, 'Order');
  const items = requireArray(body, 'items').map((item, index): OrderItemInput => {
    const record = requireRecord(item, `items[${index}]`);
    return {
      productId: requireString(record, 'productId'),
      quantity: requireInteger(record, 'quantity'),
    };
  });
  if (items.length === 0) {
    throw new ValidationError("'items' must contain at least one item");
  }
  return { customerId: requireString(body, 'customerId'), items };
}

